import{_ as a,o as e,c as t,a5 as s}from"./chunks/framework.QWVCgkrI.js";const c=JSON.parse('{"title":"3DCG・グラフィックスの用語集","description":"","frontmatter":{"title":"3DCG・グラフィックスの用語集","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"reference","format":"glossary","domain":"terms","summary":"3DCG・グラフィックスで使う語の定義、用例、関連する解説記事。"}},"headers":[],"relativePath":"glossary/graphics.md","filePath":"glossary/graphics.md"}'),n={name:"glossary/graphics.md"};function o(g,r,l,p,h,i){return e(),t("div",null,[...r[0]||(r[0]=[s('<h1 id="_3dcg・グラフィックスの用語集" tabindex="-1">3DCG・グラフィックスの用語集 <a class="header-anchor" href="#_3dcg・グラフィックスの用語集" aria-label="Permalink to &quot;3DCG・グラフィックスの用語集&quot;">​</a></h1><p><a href="/study/glossary/">用語集の入口・全用語検索</a></p><p>読み順で 59 項目を掲載しています。</p><h2 id="alpha" tabindex="-1">アルファ <a class="header-anchor" href="#alpha" aria-label="Permalink to &quot;アルファ {#alpha}&quot;">​</a></h2><p><strong>Alpha / Alpha Channel</strong> ／ 読み あるふぁ</p><p>合成時に色の寄与を制御する成分。通常の透明合成では0が透明、1が不透明を表す。</p><p><strong>この分野での意味</strong>　用途によっては画素を覆う割合を表したり、テクスチャのAチャンネルを材質のマスクなど別のデータに使ったりする。</p><p><strong>例</strong>　煙の端でアルファを0に近づける。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/output-merger.html">出力マージャー</a> · <a href="/study/glossary/graphics.html#alpha-test">アルファテスト（アルファクリップ）</a> · <a href="/study/glossary/graphics.html#alpha-blend">アルファブレンド</a> · <a href="/study/glossary/graphics.html#premultiplied-alpha">プリマルチプライドアルファ（乗算済みアルファ）</a></p><p><strong>出典</strong>　<a href="https://www.w3.org/TR/compositing-1/#simplealphacompositing" target="_blank" rel="noreferrer">W3C Compositing and Blending Level 1 — Simple Alpha Compositing</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="alpha-test" tabindex="-1">アルファテスト（アルファクリップ） <a class="header-anchor" href="#alpha-test" aria-label="Permalink to &quot;アルファテスト（アルファクリップ） {#alpha-test}&quot;">​</a></h2><p><strong>Alpha Test / Alpha Clip / Alpha Cutout</strong> ／ 読み あるふぁてすと / あるふぁくりっぷ</p><p>アルファをしきい値などと比較して、そのフラグメントを残すか捨てるか決める処理。</p><p><strong>この分野での意味</strong>　Direct3D 9には固定機能のアルファテストがあった。プログラマブルな描画ではシェーダーの破棄命令などで実装する。</p><p><strong>例</strong>　葉の透明部分をアルファクリップで抜く。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/fragment-shader.html">フラグメントシェーダー</a> · <a href="/study/glossary/graphics.html#alpha">アルファ</a> · <a href="/study/glossary/graphics.html#alpha-blend">アルファブレンド</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d9/alpha-testing-state" target="_blank" rel="noreferrer">Microsoft Direct3D 9 — Alpha Testing State</a> · <a href="https://www.w3.org/TR/2026/CRD-WGSL-20261106/" target="_blank" rel="noreferrer">W3C WGSL Candidate Recommendation Draft（2026年11月6日）</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="alpha-blend" tabindex="-1">アルファブレンド <a class="header-anchor" href="#alpha-blend" aria-label="Permalink to &quot;アルファブレンド {#alpha-blend}&quot;">​</a></h2><p><strong>Alpha Blending</strong> ／ 読み あるふぁぶれんど</p><p>アルファに応じて手前の色と背景色の寄与を変え、半透明に合成する処理。</p><p><strong>例</strong>　煙を奥から手前の順にアルファブレンドする。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/output-merger.html">出力マージャー</a> · <a href="/study/glossary/graphics.html#alpha-test">アルファテスト（アルファクリップ）</a> · <a href="/study/glossary/graphics.html#premultiplied-alpha">プリマルチプライドアルファ（乗算済みアルファ）</a> · <a href="/study/glossary/graphics.html#overdraw">オーバードロー</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/framebuffer.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — The Framebuffer</a> · <a href="https://www.w3.org/TR/compositing-1/#simplealphacompositing" target="_blank" rel="noreferrer">W3C Compositing and Blending Level 1 — Simple Alpha Compositing</a></p><h2 id="ao" tabindex="-1">アンビエントオクルージョン（AO） <a class="header-anchor" href="#ao" aria-label="Permalink to &quot;アンビエントオクルージョン（AO） {#ao}&quot;">​</a></h2><p><strong>Ambient Occlusion (AO)</strong> ／ 読み あんびえんとおくるーじょん / えーおー</p><p>周囲の形状によって、表面に届く環境光がどの程度遮られるかを近似する。</p><p><strong>この分野での意味</strong>　テクスチャに焼く方式と、画面の情報から描画中に求める方式がある。</p><p><strong>例</strong>　岩のくぼみのAOをテクスチャへ焼く。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/ssao.html">SSAOと遮蔽の近似</a> · <a href="/study/glossary/graphics.html#bake">ベイク（焼き込み）</a> · <a href="/study/glossary/graphics.html#lightmap">ライトマップ</a></p><p><strong>出典</strong>　<a href="https://docs.blender.org/manual/en/5.0/render/cycles/baking.html" target="_blank" rel="noreferrer">Blender 5.0 — Render Baking</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="instancing" tabindex="-1">インスタンシング <a class="header-anchor" href="#instancing" aria-label="Permalink to &quot;インスタンシング {#instancing}&quot;">​</a></h2><p><strong>Instancing / GPU Instancing</strong> ／ 読み いんすたんしんぐ</p><p>一つの描画命令で同じジオメトリの複数の個体を描く。位置や色などは個体ごとのデータから読み分ける。</p><p><strong>例</strong>　木のメッシュをインスタンシングして、個体ごとに位置と回転を変える。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/gpu-driven.html">GPU駆動描画</a> · <a href="/study/glossary/graphics.html#draw-call">ドローコール</a> · <a href="/study/glossary/graphics.html#batching">バッチング</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/drawing.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Drawing Commands</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/optimizing-draw-calls-choose-method.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — ドローコールの最適化方式</a></p><h2 id="weight" tabindex="-1">ウェイト（重み） <a class="header-anchor" href="#weight" aria-label="Permalink to &quot;ウェイト（重み） {#weight}&quot;">​</a></h2><p><strong>Weight / Skin Weight</strong> ／ 読み うぇいと / おもみ</p><p>スキニングで、各ジョイントの変換が頂点の位置などにどの程度効くかを表す係数。</p><p><strong>この分野での意味</strong>　アニメーションの合成では、各姿勢が結果へ寄与する割合もウェイトと呼ぶ。</p><p><strong>例</strong>　肘の頂点に上腕と前腕のウェイトを付ける。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/rigs-and-skinning.html">リグ・骨格・スキニング</a> · <a href="/study/glossary/graphics.html#skinning">スキニング</a> · <a href="/study/glossary/graphics.html#blend">ブレンド</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a> · <a href="https://docs.unity3d.com/Packages/com.unity.animation.rigging@1.4/manual/RiggingWorkflow.html" target="_blank" rel="noreferrer">Unity Animation Rigging 1.4 — Rigging Workflow</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/class-BlendTree.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Animation Blend Trees</a></p><h2 id="hdr" tabindex="-1">HDR（ハイダイナミックレンジ） <a class="header-anchor" href="#hdr" aria-label="Permalink to &quot;HDR（ハイダイナミックレンジ） {#hdr}&quot;">​</a></h2><p><strong>High Dynamic Range (HDR)</strong> ／ 読み えいちでぃーあーる / はいだいなみっくれんじ</p><p>暗部と明部の広い明るさの範囲を扱う表現。</p><p><strong>この分野での意味</strong>　HDRレンダーターゲットは計算中の広い範囲を保存する。HDR表示は出力の符号化やディスプレイまで含めた別の条件を持つ。</p><p><strong>例</strong>　HDRバッファへ光を蓄積し、画面の明るさ範囲へマッピングする。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#render-target">レンダーターゲット</a> · <a href="/study/glossary/graphics.html#tone-mapping">トーンマッピング</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/direct3darticles/high-dynamic-range" target="_blank" rel="noreferrer">Microsoft DirectX — Advanced Color</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/color-grading-and-the-filmic-tonemapper-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Color Grading and the Filmic Tonemapper</a></p><h2 id="aliasing" tabindex="-1">エイリアシング <a class="header-anchor" href="#aliasing" aria-label="Permalink to &quot;エイリアシング {#aliasing}&quot;">​</a></h2><p><strong>Aliasing</strong> ／ 読み えいりあしんぐ</p><p>細かな変化を粗い間隔でサンプリングし、元と異なる模様や動きが見える現象。モアレや輪郭のギザギザとして現れる。</p><p><strong>この分野での意味</strong>　描画では空間・時間のサンプリングの話。プログラミングでは、別の名前や参照が同じ領域を指すことも指す。</p><p><strong>例</strong>　細い格子が遠くでモアレに見える。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシングとMSAA</a> · <a href="/study/glossary/graphics.html#jaggies">ジャギー</a> · <a href="/study/glossary/graphics.html#flicker">フリッカー（ちらつき）</a> · <a href="/study/glossary/graphics.html#mipmap">ミップマップ</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">Khronos OpenGL ES 3.0.6仕様 §3.3 Multisampling</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/temporal-super-resolution-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Temporal Super Resolution</a></p><h2 id="overdraw" tabindex="-1">オーバードロー <a class="header-anchor" href="#overdraw" aria-label="Permalink to &quot;オーバードロー {#overdraw}&quot;">​</a></h2><p><strong>Overdraw</strong> ／ 読み おーばーどろー</p><p>同じ画素の位置を複数の図形が覆い、重ねて描画処理すること。半透明の合成では複数の層が最終色に寄与する。</p><p><strong>例</strong>　煙を何枚も重ねると、画面中央のオーバードローが増える。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/basics.html">GPU最適化の基礎</a> · <a href="/study/glossary/graphics.html#fill-rate">フィルレート</a> · <a href="/study/glossary/graphics.html#alpha-blend">アルファブレンド</a></p><p><strong>出典</strong>　<a href="https://developer.nvidia.com/gpugems/gpugems3/part-iv-image-effects/chapter-23-high-speed-screen-particles" target="_blank" rel="noreferrer">NVIDIA GPU Gems 3 — High-Speed, Off-Screen Particles</a></p><h2 id="kernel" tabindex="-1">カーネル（GPU計算） <a class="header-anchor" href="#kernel" aria-label="Permalink to &quot;カーネル（GPU計算） {#kernel}&quot;">​</a></h2><p><strong>GPU Kernel / Compute Kernel</strong> ／ 読み かーねる / こんぴゅーとかーねる</p><p>GPUで並列実行する処理の入口となる関数。起動時に指定した複数のスレッドなどが、それぞれの入力を処理する。</p><p><strong>この分野での意味</strong>　画像処理で「フィルターカーネル」と言う場合は、近傍の画素を混ぜるための重みの並びを指す。</p><p><strong>例</strong>　各パーティクルの位置を一つのComputeカーネルで更新する。</p><p><strong>関連</strong>　<a href="/study/graphics/compute/compute-shader.html">コンピュートシェーダー</a> · <a href="/study/glossary/graphics.html#shader">シェーダー</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a></p><p><strong>出典</strong>　<a href="https://docs.nvidia.com/cuda/archive/13.1.1/cuda-programming-guide/02-basics/intro-to-cuda-cpp.html" target="_blank" rel="noreferrer">NVIDIA CUDA 13.1.1 — CUDA C++のカーネル</a> · <a href="https://www.w3.org/TR/2026/CRD-WGSL-20261106/" target="_blank" rel="noreferrer">W3C WGSL Candidate Recommendation Draft（2026年11月6日）</a> · <a href="https://developer.nvidia.com/gpugems/gpugems/part-iv-image-processing/chapter-21-real-time-glow" target="_blank" rel="noreferrer">NVIDIA GPU Gems — Real-Time Glowと畳み込みカーネル</a></p><h2 id="pixel" tabindex="-1">画素（ピクセル） <a class="header-anchor" href="#pixel" aria-label="Permalink to &quot;画素（ピクセル） {#pixel}&quot;">​</a></h2><p><strong>Pixel / Picture Element</strong> ／ 読み がそ / ぴくせる</p><p>デジタル画像や描画先を構成する格子の一要素。</p><p><strong>この分野での意味</strong>　同じ画素に複数のフラグメントが重なり得る。マルチサンプリング時には画素の内部に複数のサンプル位置を置く。</p><p><strong>例</strong>　4つのサンプルの値を1画素にまとめる。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシングとMSAA</a> · <a href="/study/glossary/graphics.html#fragment">フラグメント</a> · <a href="/study/glossary/graphics.html#texel">テクセル</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a> · <a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">Khronos OpenGL ES 3.0.6仕様 §3.3 Multisampling</a></p><h2 id="culling" tabindex="-1">カリング <a class="header-anchor" href="#culling" aria-label="Permalink to &quot;カリング {#culling}&quot;">​</a></h2><p><strong>Culling</strong> ／ 読み かりんぐ</p><p>描画に寄与しないと判定した対象を処理から外すこと。視錐台外、遮蔽、裏面など、除外する条件で方式を呼び分ける。</p><p><strong>例</strong>　カメラの視野から完全に外れた敵を視錐台カリングで除く。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a> · <a href="/study/glossary/graphics.html#rasterize">ラスタライズ</a> · <a href="/study/glossary/graphics.html#lod">詳細度（LOD）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/visibility-and-occlusion-culling-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Visibility and Occlusion Culling</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a></p><h2 id="gamma" tabindex="-1">ガンマ <a class="header-anchor" href="#gamma" aria-label="Permalink to &quot;ガンマ {#gamma}&quot;">​</a></h2><p><strong>Gamma / Gamma Encoding</strong> ／ 読み がんま</p><p>色の明るさを非線形に符号化・変換する関係を指す言い方。狭い意味ではべき乗曲線の指数を指す。</p><p><strong>この分野での意味</strong>　sRGBも慣用的にガンマ符号化と呼ぶ。正確なsRGB曲線は区分的に定義される。</p><p><strong>例</strong>　sRGBの色テクスチャをリニア値へ戻してから照明に使う。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#linear">リニア（色）</a> · <a href="/study/glossary/graphics.html#hdr">HDR（ハイダイナミックレンジ）</a></p><p><strong>出典</strong>　<a href="https://www.w3.org/TR/css-color-4/#color-conversion-code" target="_blank" rel="noreferrer">W3C CSS Color Level 4 — 色の変換コード</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3darticles/high-dynamic-range" target="_blank" rel="noreferrer">Microsoft DirectX — Advanced Color</a></p><h2 id="quad" tabindex="-1">クアッド（四角形） <a class="header-anchor" href="#quad" aria-label="Permalink to &quot;クアッド（四角形） {#quad}&quot;">​</a></h2><p><strong>Quad / Quadrilateral</strong> ／ 読み くあっど / しかくけい</p><p>モデリングでは4頂点で囲む面。三角形を使う描画では二つの三角形へ分けられる。</p><p><strong>この分野での意味</strong>　GPUのフラグメント処理では、画面上の2×2の処理単位をクアッドと呼ぶこともある。</p><p><strong>例</strong>　クアッド主体でモデリングし、書き出しで三角形に分ける。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a> · <a href="/study/glossary/graphics.html#triangle">トライアングル（三角形）</a> · <a href="/study/glossary/graphics.html#topology">トポロジー</a> · <a href="/study/glossary/graphics.html#fragment">フラグメント</a></p><p><strong>出典</strong>　<a href="https://docs.blender.org/manual/en/5.0/modeling/meshes/primitives.html" target="_blank" rel="noreferrer">Blender 5.0 — Mesh Primitives</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a></p><h2 id="ghosting" tabindex="-1">ゴースト（残像） <a class="header-anchor" href="#ghosting" aria-label="Permalink to &quot;ゴースト（残像） {#ghosting}&quot;">​</a></h2><p><strong>Ghosting</strong> ／ 読み ごーすと / ざんぞう</p><p>動く物体の後ろなどに、以前の像が重なって残る現象。時間方向の描画処理では、過去の画素をずれた位置で再利用したときなどに起きる。</p><p><strong>この分野での意味</strong>　ディスプレイの応答による残像もゴーストと呼ぶ。描画処理の履歴によるものとは切り分けて調べる。</p><p><strong>例</strong>　武器を振ると跡が残るので、モーションベクトルと履歴の棄却を調べる。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/taa.html">TAAとフレーム履歴</a> · <a href="/study/glossary/graphics.html#flicker">フリッカー（ちらつき）</a> · <a href="/study/glossary/graphics.html#frame">フレーム（描画）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/temporal-super-resolution-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Temporal Super Resolution</a> · <a href="https://esupportdownload.benq.com/esupport/LCD%20Monitor/UserManual/LCD%20Monitor_um_User%20Manual_20070119_171207_fp93GS-en.pdf" target="_blank" rel="noreferrer">BenQ — LCDディスプレイの応答時間とゴースト</a></p><h2 id="g-buffer" tabindex="-1">Gバッファ <a class="header-anchor" href="#g-buffer" aria-label="Permalink to &quot;Gバッファ {#g-buffer}&quot;">​</a></h2><p><strong>Geometry Buffer (G-Buffer)</strong> ／ 読み じーばっふぁ</p><p>後のライティング処理で参照するため、画面上の表面の法線や材質情報などを格納するバッファ群。</p><p><strong>例</strong>　Gバッファの粗さを読み、光源の反射を計算する。</p><p><strong>関連</strong>　<a href="/study/graphics/path/deferred.html">Deferred RenderingとGバッファ</a> · <a href="/study/glossary/graphics.html#render-target">レンダーターゲット</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/post-process-materials-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Post Process Materials</a></p><h2 id="shader" tabindex="-1">シェーダー <a class="header-anchor" href="#shader" aria-label="Permalink to &quot;シェーダー {#shader}&quot;">​</a></h2><p><strong>Shader</strong> ／ 読み しぇーだー</p><p>頂点や画素の処理、汎用計算など、GPUの処理段階で実行するプログラム。</p><p><strong>この分野での意味</strong>　エンジンの制作会話では、材質の設定やそのシェーダーを組み合わせた見た目全体を指すこともある。Unity 6.3 LTSのマテリアルはシェーダーと設定値を参照する。</p><p><strong>例</strong>　頂点シェーダーで草を揺らし、フラグメントシェーダーで色を計算する。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/overview.html">シェーダー言語の全体像</a> · <a href="/study/glossary/graphics.html#material">マテリアル（材質）</a> · <a href="/study/glossary/graphics.html#pipeline">描画パイプライン</a> · <a href="/study/glossary/graphics.html#kernel">カーネル（GPU計算）</a></p><p><strong>出典</strong>　<a href="https://www.w3.org/TR/2026/CRD-WGSL-20261106/" target="_blank" rel="noreferrer">W3C WGSL Candidate Recommendation Draft（2026年11月6日）</a> · <a href="https://docs.unity.com/en-us/engine/6000.3/manual/materials-and-shaders/materials" target="_blank" rel="noreferrer">Unity 6.3 LTS — マテリアルとシェーダー</a></p><h2 id="jaggies" tabindex="-1">ジャギー <a class="header-anchor" href="#jaggies" aria-label="Permalink to &quot;ジャギー {#jaggies}&quot;">​</a></h2><p><strong>Jaggies / Jagged Edges</strong> ／ 読み じゃぎー</p><p>斜め線や曲線の輪郭が、画素の格子に沿った階段状に見える現象。</p><p><strong>例</strong>　斜めの輪郭のジャギーをMSAA（Multisample Anti-Aliasing）で抑える。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/antialiasing.html">アンチエイリアシングとMSAA</a> · <a href="/study/glossary/graphics.html#aliasing">エイリアシング</a> · <a href="/study/glossary/graphics.html#pixel">画素（ピクセル）</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/es_spec_3.0.pdf" target="_blank" rel="noreferrer">Khronos OpenGL ES 3.0.6仕様 §3.3 Multisampling</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a></p><h2 id="shadow-acne" tabindex="-1">シャドウアクネ <a class="header-anchor" href="#shadow-acne" aria-label="Permalink to &quot;シャドウアクネ {#shadow-acne}&quot;">​</a></h2><p><strong>Shadow Acne</strong> ／ 読み しゃどうあくね</p><p>シャドウマップの精度やサンプリングの誤差で、光が当たる面に誤った自己遮蔽が点や縞として現れること。</p><p><strong>例</strong>　斜めの壁にシャドウアクネが出たので、深度バイアスを調整する。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/shadow.html">影とシャドウマッピング</a> · <a href="/study/glossary/graphics.html#shadow-map">シャドウマップ</a> · <a href="/study/glossary/graphics.html#peter-panning">ピーターパン（ピーターパニング）</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/dxtecharts/common-techniques-to-improve-shadow-depth-maps" target="_blank" rel="noreferrer">Microsoft Direct3D 11 — Common Techniques to Improve Shadow Depth Maps</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ShadowPerformance.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Troubleshooting shadows</a></p><h2 id="shadow-map" tabindex="-1">シャドウマップ <a class="header-anchor" href="#shadow-map" aria-label="Permalink to &quot;シャドウマップ {#shadow-map}&quot;">​</a></h2><p><strong>Shadow Map</strong> ／ 読み しゃどうまっぷ</p><p>光源から見て最初に当たる面の深度を記録したテクスチャ。照らされる点の深度と比較し、光が遮られているかを調べる。</p><p><strong>例</strong>　太陽光のシャドウマップを描いてから、カメラ側の描画で比較する。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/shadow.html">影とシャドウマッピング</a> · <a href="/study/glossary/graphics.html#shadow-acne">シャドウアクネ</a> · <a href="/study/glossary/graphics.html#peter-panning">ピーターパン（ピーターパニング）</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/dxtecharts/common-techniques-to-improve-shadow-depth-maps" target="_blank" rel="noreferrer">Microsoft Direct3D 11 — Common Techniques to Improve Shadow Depth Maps</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ShadowPerformance.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Troubleshooting shadows</a></p><h2 id="lod" tabindex="-1">詳細度（LOD） <a class="header-anchor" href="#lod" aria-label="Permalink to &quot;詳細度（LOD） {#lod}&quot;">​</a></h2><p><strong>Level of Detail (LOD)</strong> ／ 読み しょうさいど / えるおーでぃー</p><p>画面上の大きさなどに応じて表現の細かさを変える仕組み。遠くの物体を少ない頂点で描くなど、負荷と見た目を調整する。</p><p><strong>この分野での意味</strong>　テクスチャのサンプリングでは、どのミップレベルを使うか決める値もLODと呼ぶ。</p><p><strong>例</strong>　遠景の木を低い詳細度のメッシュへ切り替える。</p><p><strong>関連</strong>　<a href="/study/graphics/texture/terrain-and-virtual-texturing.html">地形とバーチャルテクスチャ</a> · <a href="/study/glossary/graphics.html#mipmap">ミップマップ</a> · <a href="/study/glossary/graphics.html#culling">カリング</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/LevelOfDetail.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Level of Detail</a> · <a href="https://registry.khronos.org/OpenGL/specs/gl/glspec46.core.pdf" target="_blank" rel="noreferrer">Khronos OpenGL 4.6 Core仕様 §8 Textures</a></p><h2 id="skinning" tabindex="-1">スキニング <a class="header-anchor" href="#skinning" aria-label="Permalink to &quot;スキニング {#skinning}&quot;">​</a></h2><p><strong>Skinning / Skeletal Skinning</strong> ／ 読み すきにんぐ</p><p>骨格の姿勢と頂点ごとの重みに従って、メッシュの頂点を変形させる処理。</p><p><strong>この分野での意味</strong>　制作現場では、メッシュを骨格にバインドして重みを調整する作業もスキニングと呼ぶ。</p><p><strong>例</strong>　GPUで腕の頂点をスキニングする。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/rigs-and-skinning.html">リグ・骨格・スキニング</a> · <a href="/study/glossary/graphics.html#rigging">リギング</a> · <a href="/study/glossary/graphics.html#weight">ウェイト（重み）</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a> · <a href="https://docs.unity3d.com/Packages/com.unity.animation.rigging@1.4/manual/RiggingWorkflow.html" target="_blank" rel="noreferrer">Unity Animation Rigging 1.4 — Rigging Workflow</a></p><h2 id="tangent-space" tabindex="-1">接空間 <a class="header-anchor" href="#tangent-space" aria-label="Permalink to &quot;接空間 {#tangent-space}&quot;">​</a></h2><p><strong>Tangent Space</strong> ／ 読み せっくうかん</p><p>表面の局所的な接線、従接線、法線を軸にした座標系。接空間法線マップはこの基準で法線の向きを保存する。</p><p><strong>例</strong>　接空間で読んだ法線をTBN（Tangent、Bitangent、Normal）でワールド空間へ変換する。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/normal-mapping.html">法線マップと接空間</a> · <a href="/study/glossary/graphics.html#normal-map">法線マップ（ノーマルマップ）</a> · <a href="/study/glossary/graphics.html#uv">UV座標</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a> · <a href="https://github.com/mmikk/MikkTSpace/blob/master/mikktspace.h" target="_blank" rel="noreferrer">Morten S. Mikkelsen — MikkTSpace参照実装</a></p><h2 id="z-fighting" tabindex="-1">Zファイティング <a class="header-anchor" href="#z-fighting" aria-label="Permalink to &quot;Zファイティング {#z-fighting}&quot;">​</a></h2><p><strong>Z-fighting / Depth Fighting</strong> ／ 読み ぜっとふぁいてぃんぐ</p><p>同じか非常に近い深度にある面を深度バッファで安定して区別できず、表示が縞状に混じったりちらついたりする現象。</p><p><strong>例</strong>　床の上に同じ高さの面を置いたらZファイティングが起きた。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/rasterization.html">ラスタライザーと深度</a> · <a href="/study/glossary/graphics.html#flicker">フリッカー（ちらつき）</a> · <a href="/study/glossary/graphics.html#rasterize">ラスタライズ</a></p><p><strong>出典</strong>　<a href="https://developer.nvidia.com/blog/visualizing-depth-precision/" target="_blank" rel="noreferrer">NVIDIA — Visualizing Depth Precision</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a></p><h2 id="dither" tabindex="-1">ディザ（ディザリング） <a class="header-anchor" href="#dither" aria-label="Permalink to &quot;ディザ（ディザリング） {#dither}&quot;">​</a></h2><p><strong>Dither / Dithering</strong> ／ 読み でぃざ / でぃざりんぐ</p><p>近い色を細かなパターンやノイズとして分散させ、量子化による目立つ段差を粒状の変化に置き換える手法。</p><p><strong>この分野での意味</strong>　不透明・透明の細かなパターンで、部分的な被覆や段階的な消失を表すこともある。</p><p><strong>例</strong>　8ビットへ変換する前にディザを入れ、空の色の段差を目立ちにくくする。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#banding">バンディング（色の段差）</a> · <a href="/study/glossary/graphics.html#alpha-test">アルファテスト（アルファクリップ）</a></p><p><strong>出典</strong>　<a href="https://docs.blender.org/manual/en/5.0/render/output/properties/post_processing.html" target="_blank" rel="noreferrer">Blender 5.0 — Post Processing / Dither</a> · <a href="https://docs.unity.com/ja-jp/engine/6000.3/manual/render-pipelines/universal-render-pipeline/urp-reference/universalrp-asset" target="_blank" rel="noreferrer">Unity 6.3 LTS — URPのLOD Cross Fade Dithering</a></p><h2 id="atlas" tabindex="-1">テクスチャアトラス <a class="header-anchor" href="#atlas" aria-label="Permalink to &quot;テクスチャアトラス {#atlas}&quot;">​</a></h2><p><strong>Texture Atlas / Sprite Atlas</strong> ／ 読み てくすちゃあとらす / あとらす</p><p>複数の画像を大きなテクスチャの別々の領域へ詰めたもの。各画像はUVなどで自分の領域を指定して使う。</p><p><strong>例</strong>　UIのアイコンを一つのアトラスに詰める。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/materials-textures-and-shaders.html">材質・テクスチャ・シェーダーの基本</a> · <a href="/study/glossary/graphics.html#uv">UV座標</a> · <a href="/study/glossary/graphics.html#batching">バッチング</a></p><p><strong>出典</strong>　<a href="https://docs.unity.com/ja-jp/engine/6000.3/manual/unity2d/sprite/atlas/atlas-introduction" target="_blank" rel="noreferrer">Unity 6.3 LTS — スプライトアトラス</a></p><h2 id="texel" tabindex="-1">テクセル <a class="header-anchor" href="#texel" aria-label="Permalink to &quot;テクセル {#texel}&quot;">​</a></h2><p><strong>Texel / Texture Element</strong> ／ 読み てくせる</p><p>テクスチャを構成する一つの要素。色のほか、法線や深度などの値も格納できる。</p><p><strong>この分野での意味</strong>　画面の画素とテクセルは別の格子にある。サンプリングでは一つの画素に複数のテクセルが寄与することがある。</p><p><strong>例</strong>　バイリニアで近傍の4テクセルを混ぜる。</p><p><strong>関連</strong>　<a href="/study/graphics/texture/texture-filtering-and-mipmaps.html">テクスチャのフィルタリングとミップマップ</a> · <a href="/study/glossary/graphics.html#pixel">画素（ピクセル）</a> · <a href="/study/glossary/graphics.html#uv">UV座標</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/OpenGL/specs/gl/glspec46.core.pdf" target="_blank" rel="noreferrer">Khronos OpenGL 4.6 Core仕様 §8 Textures</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="tone-mapping" tabindex="-1">トーンマッピング <a class="header-anchor" href="#tone-mapping" aria-label="Permalink to &quot;トーンマッピング {#tone-mapping}&quot;">​</a></h2><p><strong>Tone Mapping</strong> ／ 読み とーんまっぴんぐ</p><p>描画結果の明るさを、表示先で扱える範囲や意図する見た目に合わせて変換する処理。</p><p><strong>例</strong>　強い発光をトーンマッピングで圧縮し、明部の階調を残す。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#hdr">HDR（ハイダイナミックレンジ）</a> · <a href="/study/glossary/graphics.html#post-process">ポストプロセス</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/color-grading-and-the-filmic-tonemapper-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Color Grading and the Filmic Tonemapper</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3darticles/high-dynamic-range" target="_blank" rel="noreferrer">Microsoft DirectX — Advanced Color</a></p><h2 id="topology" tabindex="-1">トポロジー <a class="header-anchor" href="#topology" aria-label="Permalink to &quot;トポロジー {#topology}&quot;">​</a></h2><p><strong>Topology / Mesh Topology / Primitive Topology</strong> ／ 読み とぽろじー</p><p>メッシュでは頂点・辺・面がどうつながるかを指す。形状を変形しても、接続が同じならトポロジーは保たれる。</p><p><strong>この分野での意味</strong>　描画APIのプリミティブトポロジーは、頂点列を点、線、三角形リストなどとして解釈する規則。</p><p><strong>例</strong>　関節が曲がりやすいように面のつながりを作り直す。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a> · <a href="/study/glossary/graphics.html#polygon">ポリゴン</a> · <a href="/study/glossary/graphics.html#quad">クアッド（四角形）</a> · <a href="/study/glossary/graphics.html#triangle">トライアングル（三角形）</a></p><p><strong>出典</strong>　<a href="https://help.autodesk.com/cloudhelp/2026/ENU/Maya-Modeling/files/GUID-7941F97A-36E8-47FE-95D1-71412A3B3017.htm" target="_blank" rel="noreferrer">Autodesk Maya 2026 — Polygonal Modeling</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/drawing.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Drawing Commands</a></p><h2 id="triangle" tabindex="-1">トライアングル（三角形） <a class="header-anchor" href="#triangle" aria-label="Permalink to &quot;トライアングル（三角形） {#triangle}&quot;">​</a></h2><p><strong>Triangle / Tri</strong> ／ 読み とらいあんぐる / さんかっけい</p><p>3頂点で構成する面。ゲーム描画の基本的なプリミティブの一つ。</p><p><strong>例</strong>　四角形を二つのトライアングルに分けて描く。</p><p><strong>関連</strong>　<a href="/study/graphics/mesh/vertex-and-index-input.html">頂点入力とインデックス描画</a> · <a href="/study/glossary/graphics.html#polygon">ポリゴン</a> · <a href="/study/glossary/graphics.html#quad">クアッド（四角形）</a> · <a href="/study/glossary/graphics.html#rasterize">ラスタライズ</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/drawing.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Drawing Commands</a> · <a href="https://docs.blender.org/manual/en/5.0/modeling/meshes/primitives.html" target="_blank" rel="noreferrer">Blender 5.0 — Mesh Primitives</a></p><h2 id="draw-call" tabindex="-1">ドローコール <a class="header-anchor" href="#draw-call" aria-label="Permalink to &quot;ドローコール {#draw-call}&quot;">​</a></h2><p><strong>Draw Call</strong> ／ 読み どろーこーる</p><p>頂点やインデックスを指定し、描画を指示するAPI呼び出しや記録済みの描画コマンド。</p><p><strong>例</strong>　同じメッシュ100体をまとめ、1回のインスタンス描画で指示する。</p><p><strong>関連</strong>　<a href="/study/graphics/mesh/vertex-and-index-input.html">頂点入力とインデックス描画</a> · <a href="/study/glossary/graphics.html#batching">バッチング</a> · <a href="/study/glossary/graphics.html#instancing">インスタンシング</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/drawing.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Drawing Commands</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/optimizing-draw-calls-choose-method.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — ドローコールの最適化方式</a></p><h2 id="flip-normal" tabindex="-1">ノーマルの反転（法線の反転） <a class="header-anchor" href="#flip-normal" aria-label="Permalink to &quot;ノーマルの反転（法線の反転） {#flip-normal}&quot;">​</a></h2><p><strong>Flip Normals / Reverse Normals</strong> ／ 読み のーまるのはんてん / ほうせんのはんてん</p><p>法線ベクトルを逆向きにすること。モデリングツールの面の反転では、面の表裏を入れ替える場合もある。</p><p><strong>この分野での意味</strong>　法線マップで「緑を反転する」は、接空間のY成分だけの符号を変えて規約を合わせる操作。面の表裏判定は通常、描画時の頂点の回り順で決まる。</p><p><strong>例</strong>　消える面の表裏を確認し、法線マップの緑反転とは別に調べる。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/normal-mapping.html">法線マップと接空間</a> · <a href="/study/glossary/graphics.html#normal-map">法線マップ（ノーマルマップ）</a> · <a href="/study/glossary/graphics.html#culling">カリング</a> · <a href="/study/glossary/graphics.html#tangent-space">接空間</a></p><p><strong>出典</strong>　<a href="https://docs.blender.org/manual/en/5.0/modeling/meshes/editing/mesh/normals.html" target="_blank" rel="noreferrer">Blender 5.0 — Editing Normals</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="batching" tabindex="-1">バッチング <a class="header-anchor" href="#batching" aria-label="Permalink to &quot;バッチング {#batching}&quot;">​</a></h2><p><strong>Batching / Draw Batching</strong> ／ 読み ばっちんぐ</p><p>複数の描画対象をまとめ、描画命令の発行や描画状態の切り替えにかかるコストを減らすこと。</p><p><strong>この分野での意味</strong>　Unity 6.3 LTSの静的バッチングはメッシュをまとめる。SRP Batcherは描画状態の準備を効率化する機能で、ドローコール数を減らす仕組みとは役割が異なる。</p><p><strong>例</strong>　材質をそろえてバッチにまとめる。</p><p><strong>関連</strong>　<a href="/study/graphics/engine/unity-renderer.html">UnityのレンダラーとSRP</a> · <a href="/study/glossary/graphics.html#draw-call">ドローコール</a> · <a href="/study/glossary/graphics.html#instancing">インスタンシング</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/optimizing-draw-calls-choose-method.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — ドローコールの最適化方式</a></p><h2 id="banding" tabindex="-1">バンディング（色の段差） <a class="header-anchor" href="#banding" aria-label="Permalink to &quot;バンディング（色の段差） {#banding}&quot;">​</a></h2><p><strong>Banding / Color Banding</strong> ／ 読み ばんでぃんぐ / いろのだんさ</p><p>滑らかな色の勾配が、量子化などで帯状の段差に見える現象。</p><p><strong>例</strong>　暗い空のグラデーションにバンディングが見える。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#dither">ディザ（ディザリング）</a> · <a href="/study/glossary/graphics.html#hdr">HDR（ハイダイナミックレンジ）</a></p><p><strong>出典</strong>　<a href="https://docs.blender.org/manual/en/5.0/render/output/properties/post_processing.html" target="_blank" rel="noreferrer">Blender 5.0 — Post Processing / Dither</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3darticles/high-dynamic-range" target="_blank" rel="noreferrer">Microsoft DirectX — Advanced Color</a></p><h2 id="handle" tabindex="-1">ハンドル（制作ツール） <a class="header-anchor" href="#handle" aria-label="Permalink to &quot;ハンドル（制作ツール） {#handle}&quot;">​</a></h2><p><strong>Handle / Manipulator Handle</strong> ／ 読み はんどる / そうさはんどる</p><p>制作画面でドラッグするなどして、物体の位置・向き・大きさや曲線の形を調整する操作部品。</p><p><strong>例</strong>　X軸のハンドルをドラッグして、モデルを横に動かす。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a> · <a href="/study/glossary/graphics.html#rigging">リギング</a></p><p><strong>出典</strong>　<a href="https://help.autodesk.com/cloudhelp/2026/ENU/Maya-Basics/files/GUID-09D0E733-74DF-44E2-937A-C857001E45B2.htm" target="_blank" rel="noreferrer">Autodesk Maya 2026 — Scale handles</a></p><h2 id="peter-panning" tabindex="-1">ピーターパン（ピーターパニング） <a class="header-anchor" href="#peter-panning" aria-label="Permalink to &quot;ピーターパン（ピーターパニング） {#peter-panning}&quot;">​</a></h2><p><strong>Peter Panning / Peter-panning</strong> ／ 読み ぴーたーぱん / ぴーたーぱにんぐ</p><p>シャドウマップのバイアスなどで影が物体の接地位置から離れ、物体が浮いて見える現象。</p><p><strong>例</strong>　アクネ対策でバイアスを上げすぎてピーターパニングが出た。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/shadow.html">影とシャドウマッピング</a> · <a href="/study/glossary/graphics.html#shadow-acne">シャドウアクネ</a> · <a href="/study/glossary/graphics.html#shadow-map">シャドウマップ</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/dxtecharts/common-techniques-to-improve-shadow-depth-maps" target="_blank" rel="noreferrer">Microsoft Direct3D 11 — Common Techniques to Improve Shadow Depth Maps</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/ShadowPerformance.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Troubleshooting shadows</a></p><h2 id="pipeline" tabindex="-1">描画パイプライン <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;描画パイプライン {#pipeline}&quot;">​</a></h2><p><strong>Graphics Pipeline / Rendering Pipeline</strong> ／ 読み びょうがぱいぷらいん / れんだりんぐぱいぷらいん</p><p>頂点処理、ラスタライズ、フラグメント処理、出力の合成など、描画を構成する処理段階の連なり。</p><p><strong>この分野での意味</strong>　描画APIでは一つのドローを設定するパイプラインを指す場合がある。エンジンでは影やライティングなど、複数のパスを実行する順序まで含めることがある。</p><p><strong>例</strong>　パイプラインのどの段階で深度テストが行われるかを調べる。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a> · <a href="/study/glossary/graphics.html#shader">シェーダー</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/overviews-direct3d-11-graphics-pipeline" target="_blank" rel="noreferrer">Microsoft Direct3D 11 — Graphics pipeline</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/post-process-materials-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Post Process Materials</a></p><h2 id="pass" tabindex="-1">描画パス（レンダーパス） <a class="header-anchor" href="#pass" aria-label="Permalink to &quot;描画パス（レンダーパス） {#pass}&quot;">​</a></h2><p><strong>Render Pass / Rendering Pass</strong> ／ 読み びょうがぱす / れんだーぱす</p><p>描画や画像処理のひとまとまり。影の深度や最終色など、何を読み、どの描画先へ書くかで区切る。</p><p><strong>この分野での意味</strong>　Vulkan 1.4では、アタッチメントやサブパスを記述するAPI上の構造もレンダーパスと呼ぶ。</p><p><strong>例</strong>　影のパスで書いた深度テクスチャを、照明のパスで読む。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/render-pass-attachments.html">レンダーパスとアタッチメント</a> · <a href="/study/glossary/graphics.html#pipeline">描画パイプライン</a> · <a href="/study/glossary/graphics.html#render-target">レンダーターゲット</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/renderpass.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Render Pass</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/post-process-materials-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Post Process Materials</a></p><h2 id="fill-rate" tabindex="-1">フィルレート <a class="header-anchor" href="#fill-rate" aria-label="Permalink to &quot;フィルレート {#fill-rate}&quot;">​</a></h2><p><strong>Fill Rate / Pixel Fill Rate</strong> ／ 読み ふぃるれーと</p><p>GPUが単位時間に処理または出力できる画素やサンプルの量を表す性能指標。測定条件や数え方は資料ごとに確認する。</p><p><strong>例</strong>　解像度を下げると軽くなったので、フィルレートや帯域を調べる。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/basics.html">GPU最適化の基礎</a> · <a href="/study/glossary/graphics.html#overdraw">オーバードロー</a> · <a href="/study/glossary/graphics.html#pixel">画素（ピクセル）</a></p><p><strong>出典</strong>　<a href="https://developer.arm.com/community/arm-community-blogs/b/mobile-graphics-and-gaming-blog/posts/of-philosophy-and-when-is-a-pixel-not-a-pixel" target="_blank" rel="noreferrer">Arm — Fill rateとオーバードロー</a> · <a href="https://developer.nvidia.com/gpugems/gpugems3/part-iv-image-effects/chapter-23-high-speed-screen-particles" target="_blank" rel="noreferrer">NVIDIA GPU Gems 3 — High-Speed, Off-Screen Particles</a></p><h2 id="fragment" tabindex="-1">フラグメント <a class="header-anchor" href="#fragment" aria-label="Permalink to &quot;フラグメント {#fragment}&quot;">​</a></h2><p><strong>Fragment</strong> ／ 読み ふらぐめんと</p><p>プリミティブをラスタライズして得る、画面上の位置・深度・補間された属性を持つ描画候補。</p><p><strong>この分野での意味</strong>　同じ画素に複数のフラグメントが対応し、深度テストなどを経て結果が書き込まれる。通常のマルチサンプリングでは一つのフラグメントが複数のサンプルを覆うこともある。</p><p><strong>例</strong>　奥の面のフラグメントが深度テストで除かれる。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/fragment-shader.html">フラグメントシェーダー</a> · <a href="/study/glossary/graphics.html#pixel">画素（ピクセル）</a> · <a href="/study/glossary/graphics.html#rasterize">ラスタライズ</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/framebuffer.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — The Framebuffer</a></p><h2 id="flicker" tabindex="-1">フリッカー（ちらつき） <a class="header-anchor" href="#flicker" aria-label="Permalink to &quot;フリッカー（ちらつき） {#flicker}&quot;">​</a></h2><p><strong>Flicker / Flickering / Shimmering</strong> ／ 読み ふりっかー / ちらつき</p><p>連続するフレームで明るさや模様が不安定に変わり、ちらついて見える現象。</p><p><strong>この分野での意味</strong>　細い模様が画素の格子をまたぐときに出るものは、時間方向に現れたエイリアシングの一例。</p><p><strong>例</strong>　カメラを動かすと遠くの金網がちらつく。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/taa.html">TAAとフレーム履歴</a> · <a href="/study/glossary/graphics.html#aliasing">エイリアシング</a> · <a href="/study/glossary/graphics.html#ghosting">ゴースト（残像）</a> · <a href="/study/glossary/graphics.html#mipmap">ミップマップ</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/temporal-super-resolution-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Temporal Super Resolution</a> · <a href="https://registry.khronos.org/OpenGL/specs/gl/glspec46.core.pdf" target="_blank" rel="noreferrer">Khronos OpenGL 4.6 Core仕様 §8 Textures</a></p><h2 id="blit" tabindex="-1">ブリット <a class="header-anchor" href="#blit" aria-label="Permalink to &quot;ブリット {#blit}&quot;">​</a></h2><p><strong>Blit / Bit Block Transfer (BitBlt)</strong> ／ 読み ぶりっと</p><p>画像の指定領域をまとめて別の画像や描画先へ転送すること。</p><p><strong>この分野での意味</strong>　2Dでは矩形転送を指す。GPUでは拡縮やフィルター付きの転送命令や、テクスチャを読み込んで描画先へ書くパスも指す。</p><p><strong>例</strong>　オフスクリーンで作った画像を表示用のバッファへブリットする。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/render-to-texture.html">レンダーターゲットを次のパスで使う</a> · <a href="/study/glossary/graphics.html#render-target">レンダーターゲット</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/api/wingdi/nf-wingdi-bitblt" target="_blank" rel="noreferrer">Microsoft Win32 GDI — BitBlt</a> · <a href="https://docs.vulkan.org/refpages/latest/refpages/source/vkCmdBlitImage.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — vkCmdBlitImage</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/post-process-effects-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Post Process Effects</a></p><h2 id="premultiplied-alpha" tabindex="-1">プリマルチプライドアルファ（乗算済みアルファ） <a class="header-anchor" href="#premultiplied-alpha" aria-label="Permalink to &quot;プリマルチプライドアルファ（乗算済みアルファ） {#premultiplied-alpha}&quot;">​</a></h2><p><strong>Premultiplied Alpha / Associated Alpha</strong> ／ 読み ぷりまるちぷらいどあるふぁ / じょうざんずみあるふぁ</p><p>RGBにアルファをあらかじめ掛けた表現。合成式では、手前の乗算済みRGBに背景側の寄与を加える。</p><p><strong>例</strong>　透明な縁を補間しても余計な色がにじまないよう、乗算済みの色を使う。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/output-merger.html">出力マージャー</a> · <a href="/study/glossary/graphics.html#alpha-blend">アルファブレンド</a> · <a href="/study/glossary/graphics.html#linear">リニア（色）</a></p><p><strong>出典</strong>　<a href="https://www.w3.org/TR/compositing-1/#simplealphacompositing" target="_blank" rel="noreferrer">W3C Compositing and Blending Level 1 — Simple Alpha Compositing</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/framebuffer.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — The Framebuffer</a></p><h2 id="frame" tabindex="-1">フレーム（描画） <a class="header-anchor" href="#frame" aria-label="Permalink to &quot;フレーム（描画） {#frame}&quot;">​</a></h2><p><strong>Frame / Rendered Frame</strong> ／ 読み ふれーむ / びょうがふれーむ</p><p>連続して描画・表示する画像のうちの1枚、またはその1枚に対応する描画処理の単位。</p><p><strong>この分野での意味</strong>　画面に表示した枚数、アプリが描画した枚数、ゲーム状態を更新したティック数は、別々に数える場合がある。</p><p><strong>例</strong>　前のフレームの色を使ってちらつきを抑える。</p><p><strong>関連</strong>　<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a> · <a href="/study/glossary/graphics.html#ghosting">ゴースト（残像）</a></p><p><strong>出典</strong>　<a href="https://learn.microsoft.com/en-us/windows/win32/api/dxgi/nf-dxgi-idxgiswapchain-present" target="_blank" rel="noreferrer">Microsoft DXGI — IDXGISwapChain::Present</a> · <a href="https://dev.epicgames.com/documentation/unreal-engine/temporal-super-resolution-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Temporal Super Resolution</a></p><h2 id="blend" tabindex="-1">ブレンド <a class="header-anchor" href="#blend" aria-label="Permalink to &quot;ブレンド {#blend}&quot;">​</a></h2><p><strong>Blending</strong> ／ 読み ぶれんど</p><p>新しい描画結果と、描画先にすでにある値を指定した式で合成する処理。</p><p><strong>この分野での意味</strong>　アニメーションでも、複数の姿勢や動きの結果を混ぜることを指す。</p><p><strong>例</strong>　火花を加算ブレンドで重ねる。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/output-merger.html">出力マージャー</a> · <a href="/study/glossary/graphics.html#alpha-blend">アルファブレンド</a> · <a href="/study/glossary/graphics.html#premultiplied-alpha">プリマルチプライドアルファ（乗算済みアルファ）</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/framebuffer.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — The Framebuffer</a> · <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/class-BlendTree.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Animation Blend Trees</a></p><h2 id="bake" tabindex="-1">ベイク（焼き込み） <a class="header-anchor" href="#bake" aria-label="Permalink to &quot;ベイク（焼き込み） {#bake}&quot;">​</a></h2><p><strong>Bake / Baking</strong> ／ 読み べいく / やきこみ</p><p>照明、材質、変形などの計算結果を事前に求め、再利用できるデータとして保存すること。</p><p><strong>この分野での意味</strong>　ライティングでは結果をライトマップなどへ記録する。DCC（Digital Content Creation、デジタルコンテンツ制作）ではAOや法線をテクスチャに、シミュレーション結果をキャッシュに、動きをキーフレームなどに固定する。</p><p><strong>例</strong>　壁の照明をライトマップにベイクする。布のシミュレーションをベイクして再生する。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/gi.html">グローバルイルミネーション</a> · <a href="/study/glossary/graphics.html#lightmap">ライトマップ</a> · <a href="/study/glossary/graphics.html#ao">アンビエントオクルージョン（AO）</a> · <a href="/study/glossary/graphics.html#normal-map">法線マップ（ノーマルマップ）</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Lightmapping.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — ライトマップのベイク</a> · <a href="https://docs.blender.org/manual/en/5.0/render/cycles/baking.html" target="_blank" rel="noreferrer">Blender 5.0 — Render Baking</a> · <a href="https://docs.blender.org/manual/en/5.2/physics/baking.html" target="_blank" rel="noreferrer">Blender 5.2 LTS — Baking Physics Simulations</a> · <a href="https://help.autodesk.com/cloudhelp/2023/ENU/Maya-CharacterAnimation/files/GUID-1704AD41-8435-4AD4-AF29-43EF13803EAC.htm" target="_blank" rel="noreferrer">Autodesk Maya 2023 — HumanIKのベイク</a></p><h2 id="normal-map" tabindex="-1">法線マップ（ノーマルマップ） <a class="header-anchor" href="#normal-map" aria-label="Permalink to &quot;法線マップ（ノーマルマップ） {#normal-map}&quot;">​</a></h2><p><strong>Normal Map</strong> ／ 読み ほうせんまっぷ / のーまるまっぷ</p><p>照明計算に使う法線の向きを記録するテクスチャ。頂点の位置を保ったまま、表面の細かい起伏の陰影を表せる。</p><p><strong>例</strong>　高ポリゴンの溝を低ポリゴンモデル用の法線マップにベイクする。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/normal-mapping.html">法線マップと接空間</a> · <a href="/study/glossary/graphics.html#tangent-space">接空間</a> · <a href="/study/glossary/graphics.html#bake">ベイク（焼き込み）</a> · <a href="/study/glossary/graphics.html#flip-normal">ノーマルの反転（法線の反転）</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a> · <a href="https://docs.blender.org/manual/en/5.0/render/cycles/baking.html" target="_blank" rel="noreferrer">Blender 5.0 — Render Baking</a></p><h2 id="post-process" tabindex="-1">ポストプロセス <a class="header-anchor" href="#post-process" aria-label="Permalink to &quot;ポストプロセス {#post-process}&quot;">​</a></h2><p><strong>Post-processing / Post-process Effect</strong> ／ 読み ぽすとぷろせす</p><p>シーンを描いた途中結果や画像に対して行う後処理。色調整、被写界深度、モーションブラーなどがある。</p><p><strong>例</strong>　トーンマッピングをポストプロセスで行う。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/overview.html">ポストプロセスの全体像</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a> · <a href="/study/glossary/graphics.html#tone-mapping">トーンマッピング</a> · <a href="/study/glossary/graphics.html#blit">ブリット</a></p><p><strong>出典</strong>　<a href="https://dev.epicgames.com/documentation/unreal-engine/post-process-effects-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Unreal Engine 5.8 — Post Process Effects</a></p><h2 id="polygon" tabindex="-1">ポリゴン <a class="header-anchor" href="#polygon" aria-label="Permalink to &quot;ポリゴン {#polygon}&quot;">​</a></h2><p><strong>Polygon / Polygon Face</strong> ／ 読み ぽりごん</p><p>メッシュを構成する多角形の面。三角形や四角形もポリゴンに含まれる。</p><p><strong>この分野での意味</strong>　ゲームの負荷やモデルの仕様で「ポリゴン数」と言うと、描画用の三角形数を指すことがある。</p><p><strong>例</strong>　制作時の面数と、三角形に分けた後の面数を別々に確認する。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a> · <a href="/study/glossary/graphics.html#triangle">トライアングル（三角形）</a> · <a href="/study/glossary/graphics.html#quad">クアッド（四角形）</a> · <a href="/study/glossary/graphics.html#topology">トポロジー</a></p><p><strong>出典</strong>　<a href="https://help.autodesk.com/cloudhelp/2026/ENU/Maya-Modeling/files/GUID-7941F97A-36E8-47FE-95D1-71412A3B3017.htm" target="_blank" rel="noreferrer">Autodesk Maya 2026 — Polygonal Modeling</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/drawing.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Drawing Commands</a></p><h2 id="material" tabindex="-1">マテリアル（材質） <a class="header-anchor" href="#material" aria-label="Permalink to &quot;マテリアル（材質） {#material}&quot;">​</a></h2><p><strong>Material</strong> ／ 読み まてりある / ざいしつ</p><p>表面の見た目を決めるテクスチャや色、粗さなどの設定。エンジンでは、使用するシェーダーや描画設定と結び付けて扱う。</p><p><strong>例</strong>　同じシェーダーで、粗さだけ異なる二つのマテリアルを作る。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/materials-textures-and-shaders.html">材質・テクスチャ・シェーダーの基本</a> · <a href="/study/glossary/graphics.html#shader">シェーダー</a> · <a href="/study/glossary/graphics.html#look-dev">ルックデヴ</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a> · <a href="https://docs.unity.com/en-us/engine/6000.3/manual/materials-and-shaders/materials" target="_blank" rel="noreferrer">Unity 6.3 LTS — マテリアルとシェーダー</a></p><h2 id="mipmap" tabindex="-1">ミップマップ <a class="header-anchor" href="#mipmap" aria-label="Permalink to &quot;ミップマップ {#mipmap}&quot;">​</a></h2><p><strong>Mipmap / MIP Map</strong> ／ 読み みっぷまっぷ</p><p>元のテクスチャから小さい画像を段階的に用意したもの。縮小表示で適した段を読むと、細かい模様のちらつきを抑えられる。</p><p><strong>例</strong>　奥の床では粗いミップを読む。</p><p><strong>関連</strong>　<a href="/study/graphics/texture/texture-filtering-and-mipmaps.html">テクスチャのフィルタリングとミップマップ</a> · <a href="/study/glossary/graphics.html#lod">詳細度（LOD）</a> · <a href="/study/glossary/graphics.html#texel">テクセル</a> · <a href="/study/glossary/graphics.html#aliasing">エイリアシング</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/OpenGL/specs/gl/glspec46.core.pdf" target="_blank" rel="noreferrer">Khronos OpenGL 4.6 Core仕様 §8 Textures</a></p><h2 id="uv" tabindex="-1">UV座標 <a class="header-anchor" href="#uv" aria-label="Permalink to &quot;UV座標 {#uv}&quot;">​</a></h2><p><strong>UV Coordinates / Texture Coordinates</strong> ／ 読み ゆーぶいざひょう / ゆーぶい</p><p>表面のどこにテクスチャを貼るかを表す2次元座標。UとVは画像上の二つの軸を指す。</p><p><strong>例</strong>　UVの継ぎ目で同じ頂点位置に別のテクスチャ座標を割り当てる。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/materials-textures-and-shaders.html">材質・テクスチャ・シェーダーの基本</a> · <a href="/study/glossary/graphics.html#texel">テクセル</a> · <a href="/study/glossary/graphics.html#atlas">テクスチャアトラス</a> · <a href="/study/glossary/graphics.html#tangent-space">接空間</a></p><p><strong>出典</strong>　<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html" target="_blank" rel="noreferrer">Khronos glTF 2.0仕様</a></p><h2 id="lightmap" tabindex="-1">ライトマップ <a class="header-anchor" href="#lightmap" aria-label="Permalink to &quot;ライトマップ {#lightmap}&quot;">​</a></h2><p><strong>Lightmap</strong> ／ 読み らいとまっぷ</p><p>表面に当たる光の事前計算結果を、面に対応するテクスチャへ記録したもの。描画時にその値を読み取る。</p><p><strong>例</strong>　建物用のライトマップUVを分ける。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/gi.html">グローバルイルミネーション</a> · <a href="/study/glossary/graphics.html#bake">ベイク（焼き込み）</a> · <a href="/study/glossary/graphics.html#uv">UV座標</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Lightmapping.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — ライトマップのベイク</a></p><h2 id="rasterize" tabindex="-1">ラスタライズ <a class="header-anchor" href="#rasterize" aria-label="Permalink to &quot;ラスタライズ {#rasterize}&quot;">​</a></h2><p><strong>Rasterize / Rasterization</strong> ／ 読み らすたらいず</p><p>投影された三角形などが画面上のどのサンプル位置を覆うかを求め、フラグメントを作る処理。</p><p><strong>例</strong>　三角形をラスタライズして、覆ったサンプルの深度を調べる。</p><p><strong>関連</strong>　<a href="/study/graphics/pipeline/rasterization.html">ラスタライザー</a> · <a href="/study/glossary/graphics.html#fragment">フラグメント</a> · <a href="/study/glossary/graphics.html#triangle">トライアングル（三角形）</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/primsrast.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Rasterization</a></p><h2 id="rigging" tabindex="-1">リギング <a class="header-anchor" href="#rigging" aria-label="Permalink to &quot;リギング {#rigging}&quot;">​</a></h2><p><strong>Rigging</strong> ／ 読み りぎんぐ</p><p>モデルを動かすため、骨格、操作用のコントローラー、関節の制約などを組み立てる作業。</p><p><strong>例</strong>　手のコントローラーで腕が追従するようにリギングする。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/rigs-and-skinning.html">リグ・骨格・スキニング</a> · <a href="/study/glossary/graphics.html#skinning">スキニング</a> · <a href="/study/glossary/graphics.html#weight">ウェイト（重み）</a> · <a href="/study/glossary/graphics.html#handle">ハンドル（制作ツール）</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/Packages/com.unity.animation.rigging@1.4/manual/RiggingWorkflow.html" target="_blank" rel="noreferrer">Unity Animation Rigging 1.4 — Rigging Workflow</a></p><h2 id="retarget" tabindex="-1">リターゲット <a class="header-anchor" href="#retarget" aria-label="Permalink to &quot;リターゲット {#retarget}&quot;">​</a></h2><p><strong>Retarget / Animation Retargeting</strong> ／ 読み りたーげっと</p><p>あるキャラクターの動きを、関節の対応や体格の違いを扱いながら別の骨格へ移すこと。</p><p><strong>例</strong>　収録した走りを、脚の長さが違うキャラクターにリターゲットする。</p><p><strong>関連</strong>　<a href="/study/graphics/basics/animation-systems.html">アニメーションシステム</a> · <a href="/study/glossary/graphics.html#rigging">リギング</a> · <a href="/study/glossary/graphics.html#skinning">スキニング</a></p><p><strong>出典</strong>　<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/Retargeting.html" target="_blank" rel="noreferrer">Unity 6.3 LTS — Humanoidアニメーションのリターゲット</a></p><h2 id="linear" tabindex="-1">リニア（色） <a class="header-anchor" href="#linear" aria-label="Permalink to &quot;リニア（色） {#linear}&quot;">​</a></h2><p><strong>Linear Light / Linear RGB</strong> ／ 読み りにあ / りにあしょく</p><p>数値が光量に比例する表現。同じ色成分を2倍にすると、その成分の光量も2倍になる。</p><p><strong>この分野での意味</strong>　リニアフィルタリングの「リニア」は補間方法を指す。色がリニアかどうかはデータの符号化で決まる。</p><p><strong>例</strong>　色をリニアにしてから二つのライトの寄与を足す。</p><p><strong>関連</strong>　<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a> · <a href="/study/glossary/graphics.html#gamma">ガンマ</a> · <a href="/study/glossary/graphics.html#hdr">HDR（ハイダイナミックレンジ）</a></p><p><strong>出典</strong>　<a href="https://www.w3.org/TR/css-color-4/#color-conversion-code" target="_blank" rel="noreferrer">W3C CSS Color Level 4 — 色の変換コード</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3darticles/high-dynamic-range" target="_blank" rel="noreferrer">Microsoft DirectX — Advanced Color</a> · <a href="https://registry.khronos.org/OpenGL/specs/gl/glspec46.core.pdf" target="_blank" rel="noreferrer">Khronos OpenGL 4.6 Core仕様 §8 Textures</a></p><h2 id="look-dev" tabindex="-1">ルックデヴ <a class="header-anchor" href="#look-dev" aria-label="Permalink to &quot;ルックデヴ {#look-dev}&quot;">​</a></h2><p><strong>Look Development / Lookdev</strong> ／ 読み るっくでぶ / るっくでゔ</p><p>材質、テクスチャ、照明などを試し、対象をどんな見た目に仕上げるかを詰める作業。</p><p><strong>例</strong>　照明条件を切り替えて、金属の粗さをルックデヴで決める。</p><p><strong>関連</strong>　<a href="/study/graphics/lighting/pbr.html">PBRと材質のパラメーター</a> · <a href="/study/glossary/graphics.html#material">マテリアル（材質）</a> · <a href="/study/glossary/graphics.html#shader">シェーダー</a></p><p><strong>出典</strong>　<a href="https://help.autodesk.com/cloudhelp/2026/ENU/Maya-LightingShading/files/GUID-164E40B5-28E5-41AD-B573-AE33004DD6FB.htm" target="_blank" rel="noreferrer">Autodesk Maya 2026 — Hypershadeでのルックデヴ</a></p><h2 id="render-target" tabindex="-1">レンダーターゲット <a class="header-anchor" href="#render-target" aria-label="Permalink to &quot;レンダーターゲット {#render-target}&quot;">​</a></h2><p><strong>Render Target / Color Attachment</strong> ／ 読み れんだーたーげっと</p><p>描画結果を書き込む先の画像。色の出力先を指すことが多く、別のパスからテクスチャとして読む用途にも使える。</p><p><strong>例</strong>　反射用の画像をオフスクリーンのレンダーターゲットに描く。</p><p><strong>関連</strong>　<a href="/study/graphics/postprocess/render-to-texture.html">レンダーターゲットを次のパスで使う</a> · <a href="/study/glossary/graphics.html#pass">描画パス（レンダーパス）</a> · <a href="/study/glossary/graphics.html#blit">ブリット</a> · <a href="/study/glossary/graphics.html#g-buffer">Gバッファ</a></p><p><strong>出典</strong>　<a href="https://docs.vulkan.org/spec/latest/chapters/renderpass.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — Render Pass</a> · <a href="https://docs.vulkan.org/spec/latest/chapters/framebuffer.html" target="_blank" rel="noreferrer">Khronos Vulkan 1.4 — The Framebuffer</a></p>',386)])])}const m=a(n,[["render",o]]);export{c as __pageData,m as default};
